void MaybeShowOneClickSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  const std::string& sign_in_value = request->extra_request_headers().FindHeader(kSignInHeader);
  if (sign_in_value.empty())
    return;

  // Validate that the request URL is in the Gaia sign-on realm.
  GURL request_url = request->url();
  if (!request_url.SchemeIs("https") || !request_url.DomainIs("accounts.google.com"))
    return;

  // Parse sign-in values to extract email and session index.
  std::string email;
  std::string session_index;
  if (!ParseSignInValues(sign_in_value, &email, &session_index))
    return;

  // Determine auto-accept behavior based on parsed values and request source.
  bool auto_accept = false;
  if (!email.empty() && !session_index.empty()) {
    auto_accept = ShouldAutoAcceptSignIn(io_data->GetRequestSource());
  } else {
    return;
  }

