void ShowOneClickSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  std::string sign_in_values = request->request_headers().GetHeader("X-Chrome-OAuth2-Signin");
  if (sign_in_values.empty())
    return;

  GURL url(request->url());
  if (!url.SchemeIs("https") || !url.DomainIs("accounts.google.com"))
    return;

  std::string email, session_index;
  size_t pos = sign_in_values.find(',');
  if (pos != std::string::npos) {
    email = sign_in_values.substr(0, pos);
    session_index = sign_in_values.substr(pos + 1);
  }

  bool auto_accept = !email.empty() && !session_index.empty();

  if (email.empty() && session_index.empty())
    return;

  BrowserThread::PostTask(
      BrowserThread::UI,
      FROM_HERE,
      base::Bind(&ShowOneClickSignInInfoBarOnUIThread, email, session_index, auto_accept, child_id, route_id));
}

void ShowOneClickSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  const std::string& headers = request->http_info().headers();
  std::string sign_in_values;
  std::string email;
  std::string session_index;
  bool auto_accept = false;

  // Extract sign-in values from headers (example logic for demonstration).
  size_t pos = headers.find("X-Gaia-SignIn-Data:");
  if (pos != std::string::npos) {
    size_t end_pos = headers.find('\n', pos);
    sign_in_values = headers.substr(pos + strlen("X-Gaia-SignIn-Data:"));
    base::TrimWhitespaceASCII(sign_in_values, base::TRIM_ALL, &sign_in_values);

    // Parse sign-in data (this is a simplified example).
    std::vector<std::string> parts = base::SplitString(sign_in_values, ";", base::TRIM_WHITESPACE, base::SPLIT_WANT_ALL);
    for (const std::string& part : parts) {
      if (base::StartsWith(part, "email=")) {
        email = part.substr(strlen("email="));
      } else if (base::StartsWith(part, "session_index=")) {
        session_index = part.substr(strlen("session_index="));
      }
    }
  }

  if (email.empty() && session_index.empty()) {
    return;
  }

  // Validate URL against Gaia sign-on realm (example logic).
  const GURL& url = request->url();
  if (!url.SchemeIs("https") || !url.host().ends_with(".accounts.google.com")) {
    return;
  }

  // Determine auto-accept behavior based on the request source.
  if (request->request_context_type() == net::URLRequestContext::CONTEXT_TYPE_RENDERER) {
    auto_accept = true;
  }

  // Post a task to the UI thread to show the info bar with the collected data.
  content::GetUIThreadTaskRunner({})->PostTask(
      FROM_HERE,
      base::BindOnce(&ShowOneClickSignInInfoBarOnUI,
                     email,
                     session_index,
                     auto_accept,
                     child_id,
                     route_id,
                     io_data->GetWeakPtr()));
}

